# Review package: 5dfac7a..HEAD

## Commits
6d05200 Strengthen edge case test assertions

## Files changed
 greet.test.js | 9 +++------
 1 file changed, 3 insertions(+), 6 deletions(-)

## Diff
diff --git a/greet.test.js b/greet.test.js
index df402a6..af65f0d 100644
--- a/greet.test.js
+++ b/greet.test.js
@@ -7,25 +7,22 @@ test('greet returns formatted greeting with name', () => {
   assert.strictEqual(result, 'Hello, Alice!');
 });

 test('greet returns formatted greeting with different name', () => {
   const result = greet('Bob');
   assert.strictEqual(result, 'Hello, Bob!');
 });

 test('greet handles empty string gracefully', () => {
   const result = greet('');
-  assert.strictEqual(typeof result, 'string');
-  assert.ok(result.length > 0);
+  assert.strictEqual(result, 'Hello, stranger!');
 });

 test('greet handles null gracefully', () => {
   const result = greet(null);
-  assert.strictEqual(typeof result, 'string');
-  assert.ok(result.length > 0);
+  assert.strictEqual(result, 'Hello, stranger!');
 });

 test('greet handles undefined gracefully', () => {
   const result = greet(undefined);
-  assert.strictEqual(typeof result, 'string');
-  assert.ok(result.length > 0);
+  assert.strictEqual(result, 'Hello, stranger!');
 });
